python - <<'PY'
import operator
import semver
v = semver.VersionInfo('1', '2', '3', 4, 5)
assert tuple(v) == (1, 2, 3, '4', '5')
for name in ('major', 'minor', 'patch', 'prerelease', 'build'):
    try:
        setattr(v, name, 9)
    except AttributeError:
        pass
    else:
        raise AssertionError(name)
    try:
        delattr(v, name)
    except AttributeError:
        pass
    else:
        raise AssertionError(name)
for op in (operator.eq, operator.ne, operator.lt, operator.le, operator.gt, operator.ge):
    other = (1, 2, 3, '4', 'different-build')
    assert op(v, other) == op(v, semver.VersionInfo(*other))
    assert op(other, v) == op(semver.VersionInfo(*other), v)
for other in ('1.2.3', 123):
    assert v != other
    for op in (operator.lt, operator.le, operator.gt, operator.ge):
        try:
            op(v, other)
        except TypeError:
            pass
        else:
            raise AssertionError((op, other))
v = semver.VersionInfo.parse('1.2.3-rc.9+build.9')
for part in ('major', 'minor', 'patch', 'prerelease', 'build'):
    result = getattr(v, 'bump_' + part)()
    assert isinstance(result, semver.VersionInfo)
    assert str(result) == getattr(semver, 'bump_' + part)(str(v))
assert str(v) == '1.2.3-rc.9+build.9'
assert str(v.replace(major='7', prerelease=None)) == '7.2.3+build.9'
assert semver.replace(str(v), build=123) == '1.2.3-rc.9+123'
assert v.replace() is not v
try:
    v.replace(unknown=1)
except TypeError:
    pass
else:
    raise AssertionError('unknown component')
parser = semver.createparser()
assert parser.prog == 'pysemver'
assert semver.process(parser.parse_args(['compare', '1.2.3', '2.0.0'])) == -1
assert semver.process(parser.parse_args(['bump', 'patch', '1.2.3'])) == '1.2.4'
